package net

import (
	"errors"
	"net"
	"sync"
	"syscall"
	"time"
)

// Pacer spaces successive sends by at least interval.
//
// The drop point it guards is the sing-box SS2022 inbound's
// packetOutbound queue: a channel of capacity 64 drained by a
// single loopUDPOut goroutine, with non-blocking writes that
// silently drop when full. A 200-packet zero-interval burst
// arrives in ~3ms and is lost from packet 65 on; spreading the
// egress writes by one interval per packet spreads the echo
// replies the same way (each reply is generated by one egress
// packet), so the queue drains faster than packets arrive.
//
// A Pacer is per session: one exit-relay session paces its own
// datagrams, and sessions never share a grid. It is safe for
// concurrent use, although Transport drives a connection's
// writes from a single goroutine.
type Pacer struct {
	mu       sync.Mutex
	interval time.Duration
	next     time.Time // earliest instant the next packet may go
}

// NewPacer returns a Pacer spacing sends by interval. A
// non-positive interval disables pacing (Wait returns at once).
func NewPacer(interval time.Duration) *Pacer {
	return &Pacer{interval: interval}
}

// Wait blocks until the next send slot. The first call returns
// immediately and arms the grid; every later call returns no
// earlier than one interval after the previous packet's actual
// send time, so a slow write cannot collapse the spacing.
func (p *Pacer) Wait() {
	if p.interval <= 0 {
		return
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.next.IsZero() {
		p.next = time.Now().Add(p.interval)
		return
	}
	if d := time.Until(p.next); d > 0 {
		time.Sleep(d)
	}
	// Anchor the next slot to the later of the slot just
	// consumed and now: a write that overran its slot still
	// leaves a full interval before the next packet.
	next := p.next
	if now := time.Now(); now.After(next) {
		next = now
	}
	p.next = next.Add(p.interval)
}

var errPacedConnSyscallNotSupported = errors.New("paced conn: syscall conn not supported by the underlying connection")

// pacedConn is a net.Conn whose Write calls are spaced by a
// Pacer. Reads are untouched: only the egress direction is
// paced, the return path flows at line speed.
type pacedConn struct {
	net.Conn
	pacer *Pacer
}

// NewPacedConn wraps conn so each Write is spaced at least
// interval after the previous one. A non-positive interval, or a
// nil conn, returns conn unwrapped.
func NewPacedConn(conn net.Conn, interval time.Duration) net.Conn {
	if conn == nil || interval <= 0 {
		return conn
	}
	return &pacedConn{Conn: conn, pacer: NewPacer(interval)}
}

// Write paces the datagram, then delegates. One Write is one
// datagram on the UDP path, so this is per-packet pacing.
func (c *pacedConn) Write(b []byte) (int, error) {
	c.pacer.Wait()
	return c.Conn.Write(b)
}

// CloseWrite forwards a half-close when the underlying conn
// supports one, mirroring the relay tcpConn wrapper.
func (c *pacedConn) CloseWrite() error {
	if cw, ok := c.Conn.(interface{ CloseWrite() error }); ok {
		return cw.CloseWrite()
	}
	return errors.New("paced conn: half-close not supported by the underlying connection")
}

// CloseRead forwards a half-close-read when the underlying conn
// supports one.
func (c *pacedConn) CloseRead() error {
	if cr, ok := c.Conn.(interface{ CloseRead() error }); ok {
		return cr.CloseRead()
	}
	return errors.New("paced conn: half-close-read not supported by the underlying connection")
}

// SyscallConn forwards the raw socket so TCP_INFO probes and
// linger-0 teardown keep resolving through the wrapper.
func (c *pacedConn) SyscallConn() (syscall.RawConn, error) {
	if sc, ok := c.Conn.(syscall.Conn); ok {
		return sc.SyscallConn()
	}
	return nil, errPacedConnSyscallNotSupported
}
